    return '$party ਨੂੰ ਨਕਦ ਦਿੱਤਾ: ਇੱਕ ਦਿਨ ਵਿੱਚ $amount। ਇੱਕ ਵਿਅਕਤੀ ਨੂੰ ਇੱਕ ਦਿਨ ਵਿੱਚ ₹10,000 ਤੋਂ ਵੱਧ ਨਕਦ ਖਰਚਾ ਮਨਜ਼ੂਰ ਨਹੀਂ (ਧਾਰਾ 40A(3)); ਬੈਂਕ ਰਾਹੀਂ ਦਿਓ।';
  }

  @override
  String checksKindsCash269ST(String party, String amount) {
    return '$party ਤੋਂ ਨਕਦ ਮਿਲਿਆ: ਇੱਕ ਦਿਨ ਵਿੱਚ $amount। ₹2 ਲੱਖ ਜਾਂ ਵੱਧ ਨਕਦ ਲੈਣਾ ਮਨਜ਼ੂਰ ਨਹੀਂ (ਧਾਰਾ 269ST); ਜੁਰਮਾਨਾ ਉਸੇ ਰਕਮ ਦੇ ਬਰਾਬਰ।';
  }

  @override
  String checksKindsDuplicateBill(
    String supplier,
    String amount,
    String first,
    String second,
  ) {
    return '$supplier ਨੇ ਇੱਕ ਹਫ਼ਤੇ ਵਿੱਚ ਦੋ ਵਾਰ $amount ਦਾ ਬਿੱਲ ਦਿੱਤਾ ($first ਅਤੇ $second)। ਕੀ ਇੱਕ ਡੁਪਲੀਕੇਟ ਹੈ?';
  }

  @override
  String checksKindsBelowCost(
    String number,
    String item,
    String rate,
    String cost,
  ) {
    return '$number: $item $rate ਵਿੱਚ ਵੇਚੀ, ਖਰੀਦ ਰੇਟ $cost ਤੋਂ ਘੱਟ।';
  }

  @override
  String checksKindsNegativeStock(String item, String qty, String uom) {
    return '$item $qty $uom \'ਤੇ ਹੈ: ਸਟਾਕ ਤੋਂ ਵੱਧ ਵੇਚਿਆ ਜਾਂ ਦਿੱਤਾ ਗਿਆ।';
  }

